@DisplayName("음료를 0잔 담으면 예외가 난다")
@Test
void addZeroBeverages() {
    assertThatThrownBy(() -> cafeKiosk.add(new Americano(), 0))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessage("음료는 1잔 이상 주문하실 수 있습니다.");
}

