# --- remove 도 같은 방법으로 ---

#   해피     담은 음료를 빼면 목록에서 사라진다
#   예외     없는 음료를 빼면 예외가 난다        (2.2절에서 짰다)
#   경계     마지막 하나를 빼면 목록이 빈다

@DisplayName("마지막 한 잔을 빼면 목록이 빈다")
@Test
void removeLast() {
    Americano americano = new Americano();
    cafeKiosk.add(americano);

    cafeKiosk.remove(americano);

    assertThat(cafeKiosk.getBeverages()).isEmpty();
}

